import{_ as e,o as d,c as a,a5 as o}from"./chunks/framework.CyyS6Zdm.js";const u=JSON.parse('{"title":"服务与运行时","description":"","frontmatter":{},"headers":[],"relativePath":"runtime/index.md","filePath":"runtime/index.md","lastUpdated":1787174994000}'),r={name:"runtime/index.md"};function n(i,t,c,s,h,l){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="服务与运行时" tabindex="-1">服务与运行时 <a class="header-anchor" href="#服务与运行时" aria-label="Permalink to &quot;服务与运行时&quot;">​</a></h1><p>组件册收的是<strong>有解剖、有部件、能摆在页面上</strong>的东西。还有一类东西不是组件，却同样是这个库对外提供的能力：应用级的一份配置、一次调用就弹出来的对话框、一套把流式文本变成节点的内核。它们没有 <code>data-part</code>，所以进不了组件册，但你确实会用到——本册就是收这些的。</p><table tabindex="0"><thead><tr><th>这一册</th><th>是什么</th><th>对应的包</th></tr></thead><tbody><tr><td><a href="./config">全局配置</a></td><td>应用级注入一次，语言与内建文案的默认值</td><td><code>@xihan-ui/vue</code></td></tr><tr><td><a href="./services">命令式服务</a></td><td><code>confirm()</code> / <code>toast.success()</code> 这种一次调用就出结果的入口</td><td><code>@xihan-ui/vue</code></td></tr><tr><td><a href="./markdown">流式 Markdown</a></td><td>喂截至当前的全文，拿回一组带稳定 key 的已渲染块</td><td><code>@xihan-ui/markdown</code></td></tr><tr><td><a href="./code-highlight">代码着色</a></td><td>零依赖的粗粒度词法着色，也是一个可替换的端口</td><td><code>@xihan-ui/code-highlight</code></td></tr></tbody></table><h2 id="为什么它们不在组件册里" tabindex="-1">为什么它们不在组件册里 <a class="header-anchor" href="#为什么它们不在组件册里" aria-label="Permalink to &quot;为什么它们不在组件册里&quot;">​</a></h2><p>组件册每一页固定给出解剖、部件、状态机、connect API 与键盘规格，因为组件的契约就是这几样。这四样东西一样都套不上：全局配置是一个 provide 函数，命令式服务返回的是一个对象，Markdown 渲染器产出的是数据而不是 DOM。硬塞进组件册只会让那册的页内结构失去意义。</p><p>但<strong>能力清单</strong>该是完整的。如果你是照着别的组件库的心智来找东西的——Element Plus 的 <code>ElMessageBox</code>、Ant Design 的 <code>App.useApp()</code>、Naive UI 的 <code>useDialog</code>、Semi Design 的 Markdown 渲染器——它们在这里，不在组件册。</p>',6)])])}const _=e(r,[["render",n]]);export{u as __pageData,_ as default};
